import os
from xml.sax.saxutils import escape, quoteattr

from pyspark.sql import functions as F


def tag(name, value):
    return "" if value is None else f"<{name}>{escape(str(value))}</{name}>"


def attr(name, value):
    return "" if value is None else f" {name}={quoteattr(value)}"


def export(invoices, invoice_lines, path):
    """The billing export, written for you: one <invoice> per invoice, one <amount> per line, in line order."""
    lines = {}
    for line in invoice_lines.collect():
        lines.setdefault(line["invoice_id"], []).append(line)
    rows = []
    for inv in invoices.collect():
        mine = sorted(lines.get(inv["invoice_id"], []), key=lambda line: line["line_no"])
        amounts = "".join(tag("amount", line["line_amount"]) for line in mine)
        rows.append(f"  <invoice{attr('id', inv['invoice_id'])}>{tag('status', inv['status'])}{amounts}</invoice>")
    os.makedirs(os.path.dirname(path), exist_ok=True)
    with open(path, "w") as f:
        f.write("<invoices>\n" + "\n".join(rows) + "\n</invoices>\n")


def load(path):
    # Read the billing XML at `path`: one row per invoice.
    pass


def solve(invoices, invoice_lines):
    path = "/tmp/billing/invoices.xml"
    export(invoices, invoice_lines, path)
    return load(path)
